<?php $scores=array_map(function($r){return (float)$r['quality']['score'];},$teacher_quality??array());?>
<div class="row"><div class="col-12"><div class="card"><div class="card-body"><h4 class="page-title">Teacher Quality</h4><p class="text-muted mb-0">Explainable quality inputs covering content, moderation, feedback, class reliability, and engagement.</p></div></div></div></div>
<div class="row"><div class="col-md-4"><div class="card"><div class="card-body"><small>Active teachers</small><h3><?php echo count($teacher_quality??array());?></h3></div></div></div><div class="col-md-4"><div class="card"><div class="card-body"><small>Average quality score</small><h3><?php echo $scores?number_format(array_sum($scores)/count($scores),1):0;?></h3></div></div></div><div class="col-md-4"><div class="card"><div class="card-body"><small>Weighting</small><h3>25/15/20/25/15</h3><span>Content / moderation / feedback / reliability / engagement</span></div></div></div></div>
<div class="row"><div class="col-12"><div class="card"><div class="card-body"><div class="table-responsive"><table class="table table-sm table-hover"><thead><tr><th>Teacher</th><th>Score</th><th>Content 25%</th><th>Moderation 15%</th><th>Feedback 20%</th><th>Reliability 25%</th><th>Engagement 15%</th><th>Improvement action</th></tr></thead><tbody>
<?php foreach(($teacher_quality??array()) as $row):?><tr><td><strong><?php echo html_escape(trim($row['first_name'].' '.$row['last_name']));?></strong><br><small><?php echo html_escape($row['email']);?></small></td><td><span class="badge badge-<?php echo $row['quality']['score']>=80?'success':($row['quality']['score']>=60?'warning':'danger');?>"><?php echo $row['quality']['score'];?></span></td><?php foreach($row['quality']['components'] as $value):?><td><?php echo number_format((float)$value,1);?></td><?php endforeach;?><td><?php echo html_escape($row['quality']['actions'][0]??'Maintain current teaching routines.');?></td></tr><?php endforeach;?>
<?php if(empty($teacher_quality)):?><tr><td colspan="8" class="text-center text-muted">No active teachers found.</td></tr><?php endif;?></tbody></table></div>
<div class="alert alert-light border mt-3 mb-0"><strong>Interpretation:</strong> scores prioritize improvement conversations. Missing evidence uses a neutral baseline rather than penalizing a new teacher.</div>
</div></div></div></div>
